Object.assign(window.EXAMPLES=window.EXAMPLES||{},{"persia":{"t":"The Persian Empire","c":"The Achaemenid Persian Empire, founded by Cyrus the Great around 550 BC in what is now Iran, became the largest empire the world had yet seen, stretching from Egypt and the Balkans to the Indus Valley. Cyrus was known for allowing conquered peoples to keep their customs and religions. Darius I organised the empire into provinces, built the Royal Road with relay stations for messengers, standardised coins and built the palace of Persepolis. The empire fell to Alexander the Great in 330 BC, but later Persian empires rose after it.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 204\" width=\"640\" height=\"204\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"188\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#a16207\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">550 BC</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Cyrus the Great founds the Achaemenid Empire</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#a16207\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">522–486 BC</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Darius I builds roads and Persepolis</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#a16207\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">480 BC</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Xerxes invades Greece</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#a16207\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">330 BC</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Conquered by Alexander the Great</text></svg>","c":"Milestones of the Achaemenid Empire"}]},"mali":{"t":"Gold for salt in the Mali Empire","c":"The Mali Empire, founded by Sundiata Keita around 1235, controlled much of West Africa and grew rich from trans-Saharan trade, especially exchanging gold from the south for salt from mines in the Sahara, carried by camel caravans. Its cities, such as Timbuktu, became great centres of Islamic learning, with libraries holding thousands of manuscripts. Its most famous ruler, Mansa Musa, made a pilgrimage to Mecca in 1324 with such lavish spending of gold that he reportedly caused prices to fall in Cairo. Simplified.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 200\" width=\"620\" height=\"200\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"200\" rx=\"10\" fill=\"#fef3c7\"/><rect x=\"20\" y=\"60\" width=\"170\" height=\"80\" rx=\"10\" fill=\"#facc15\"/><text x=\"105\" y=\"97\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Gold from the south</text><text x=\"105\" y=\"115\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">mines of West Africa</text><path d=\"M190,100H222\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M230,100l-10,-6v12z\" fill=\"currentColor\"/><rect x=\"230\" y=\"60\" width=\"160\" height=\"80\" rx=\"10\" fill=\"#fde68a\"/><text x=\"310\" y=\"97\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Mali’s cities</text><text x=\"310\" y=\"115\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">Timbuktu, Djenné</text><path d=\"M430,100H398\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M390,100l10,-6v12z\" fill=\"currentColor\"/><rect x=\"430\" y=\"60\" width=\"170\" height=\"80\" rx=\"10\" fill=\"#e7e5e4\"/><text x=\"515\" y=\"97\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Salt from the north</text><text x=\"515\" y=\"115\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">Saharan mines</text></svg>","c":"The gold–salt trade at the heart of Mali’s wealth"}]},"opium":{"t":"The Opium Wars","c":"In the early 1800s British merchants sold large amounts of opium, grown in British India, into China to pay for Chinese tea, silk and porcelain, causing widespread addiction. When China’s Qing government seized and destroyed opium stocks in 1839, Britain went to war. China’s defeats in the First and Second Opium Wars forced it to open ports, pay compensation, legalise opium and hand Hong Kong to Britain, beginning what Chinese historians call the ‘century of humiliation’. Hong Kong was returned to China in 1997.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 204\" width=\"640\" height=\"204\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"188\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#7c2d12\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1839–42</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">First Opium War</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#7c2d12\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1842</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Treaty of Nanjing; Hong Kong ceded to Britain</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#7c2d12\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1856–60</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Second Opium War</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#7c2d12\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1997</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Hong Kong returned to China</text></svg>","c":"Key events"}]},"africacolon":{"t":"The colonisation of Africa","c":"In 1870 European powers controlled about a tenth of Africa, mostly along the coasts. In the ‘Scramble for Africa’ that followed, and after the Berlin Conference of 1884–85, Britain, France, Germany, Belgium, Portugal, Italy and Spain divided almost the whole continent among themselves within about 30 years, often drawing borders with little regard for the peoples living there. By 1914 only Ethiopia and Liberia remained independent. Colonial rule brought exploitation and violence. Most African countries regained independence between the late 1950s and the 1970s.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 246\" width=\"640\" height=\"246\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"230\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#a16207\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1884–85</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Berlin Conference sets rules for claiming Africa</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#a16207\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1914</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Most of Africa under European rule</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#a16207\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1957</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Ghana gains independence</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#a16207\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1960</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Year of Africa: 17 nations independent</text><circle cx=\"140\" cy=\"202\" r=\"8\" fill=\"#a16207\"/><text x=\"126\" y=\"207\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1994</text><text x=\"156\" y=\"207\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">End of apartheid in South Africa</text></svg>","c":"From colonisation to independence"}]},"modernchina":{"t":"China since 1949","c":"The Chinese Communist Party, led by Mao Zedong, founded the People’s Republic of China in 1949 after a long civil war. Mao’s campaigns, including the Great Leap Forward, which caused one of history’s deadliest famines, and the Cultural Revolution, brought immense suffering. From 1978, Deng Xiaoping introduced market reforms that sparked decades of rapid growth, lifting hundreds of millions of people out of poverty and making China the world’s second-largest economy. China remains a one-party state.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 288\" width=\"640\" height=\"288\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"272\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1949</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">People’s Republic of China founded</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1958–62</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Great Leap Forward; tens of millions die in famine</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1966–76</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Cultural Revolution</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1978</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Deng Xiaoping begins economic reforms</text><circle cx=\"140\" cy=\"202\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"207\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">2001</text><text x=\"156\" y=\"207\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">China joins the World Trade Organization</text><circle cx=\"140\" cy=\"244\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"249\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">2010</text><text x=\"156\" y=\"249\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Becomes world’s second-largest economy</text></svg>","c":"Key moments since 1949"}]},"greenrev":{"t":"The Green Revolution","c":"From the 1940s to the 1970s, scientists developed high-yielding varieties of wheat and rice that, with fertiliser, irrigation and pesticides, produced far more grain per hectare. Led by researchers such as Norman Borlaug, who won the Nobel Peace Prize in 1970, and institutes such as the International Rice Research Institute in the Philippines, the Green Revolution greatly increased harvests in Mexico, India, Pakistan and much of Asia, helping prevent famines. It also brought problems, including heavy chemical use, falling groundwater and benefits that favoured wealthier farmers.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 184\" width=\"620\" height=\"184\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><text x=\"100\" y=\"31\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1961</text><rect x=\"110\" y=\"12\" width=\"152.8\" height=\"28\" rx=\"5\" fill=\"#a3e635\"/><text x=\"270.82608695652175\" y=\"31\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">about 1.9 t per hectare</text><text x=\"100\" y=\"71\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1980</text><rect x=\"110\" y=\"52\" width=\"217.2\" height=\"28\" rx=\"5\" fill=\"#84cc16\"/><text x=\"335.1739130434783\" y=\"71\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">about 2.7 t</text><text x=\"100\" y=\"111\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">2000</text><rect x=\"110\" y=\"92\" width=\"313.7\" height=\"28\" rx=\"5\" fill=\"#65a30d\"/><text x=\"431.69565217391306\" y=\"111\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">about 3.9 t</text><text x=\"100\" y=\"151\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">2020</text><rect x=\"110\" y=\"132\" width=\"370.0\" height=\"28\" rx=\"5\" fill=\"#4d7c0f\"/><text x=\"488\" y=\"151\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">about 4.6 t</text></svg>","c":"Approximate average world cereal yield"}]},"oxygen":{"t":"Oxygen: the breath of life","c":"Oxygen makes up about 21 percent of the air and is the most abundant element in Earth’s crust, locked in rocks and water. Almost all of the oxygen in the air was produced by photosynthesis, first by ancient ocean microbes from about 2.4 billion years ago and later by plants and algae. Animals, including us, breathe it in to release energy from food, breathing out carbon dioxide that plants use again. Oxygen was discovered in the 1770s by Carl Scheele and Joseph Priestley, and named by Antoine Lavoisier.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 210\" width=\"620\" height=\"210\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"210\" rx=\"10\" fill=\"#f8fafc\"/><rect x=\"20\" y=\"70\" width=\"170\" height=\"70\" rx=\"10\" fill=\"#e0e7ff\"/><text x=\"105\" y=\"102\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Plants make oxygen</text><text x=\"105\" y=\"120\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">by photosynthesis</text><path d=\"M190,105H222\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M230,105l-10,-6v12z\" fill=\"currentColor\"/><rect x=\"230\" y=\"70\" width=\"160\" height=\"70\" rx=\"10\" fill=\"#bae6fd\"/><text x=\"310\" y=\"102\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Air</text><text x=\"310\" y=\"120\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">about 21% oxygen</text><path d=\"M390,105H422\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M430,105l-10,-6v12z\" fill=\"currentColor\"/><rect x=\"430\" y=\"70\" width=\"170\" height=\"70\" rx=\"10\" fill=\"#fecaca\"/><text x=\"515\" y=\"102\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Animals breathe it</text><text x=\"515\" y=\"120\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">to release energy from food</text></svg>","c":"The oxygen cycle, simplified"}]},"carbonchem":{"t":"One element, many forms","c":"Carbon atoms can bond with up to four other atoms, including other carbon atoms, in chains, rings and sheets, which is why carbon forms millions of compounds and is the basis of all known life. Pure carbon alone comes in very different forms: in diamond, every atom is locked in a rigid 3D lattice, making it extremely hard; in graphite, atoms form flat sheets that slide over each other, which is why pencils work; and graphene, a single sheet of graphite, is one of the strongest materials known.","items":[{"w":1,"s":"<svg viewBox=\"0 0 600 214\" width=\"600\" height=\"214\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"580\" height=\"58\" rx=\"10\" fill=\"#38bdf8\" fill-opacity=\".2\" stroke=\"#38bdf8\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Diamond</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Carbon atoms in a rigid 3D lattice: the hardest natural material</text><rect x=\"10\" y=\"78\" width=\"580\" height=\"58\" rx=\"10\" fill=\"#475569\" fill-opacity=\".2\" stroke=\"#475569\"/><text x=\"24\" y=\"106\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Graphite</text><text x=\"24\" y=\"126\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Flat sheets that slide: pencil ‘lead’</text><rect x=\"10\" y=\"146\" width=\"580\" height=\"58\" rx=\"10\" fill=\"#94a3b8\" fill-opacity=\".2\" stroke=\"#94a3b8\"/><text x=\"24\" y=\"174\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Graphene</text><text x=\"24\" y=\"194\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">A single sheet one atom thick: very strong</text></svg>","c":"Three forms of pure carbon"}]},"nobel":{"t":"The Nobel Prize categories","c":"The Nobel Prizes were established by the will of Alfred Nobel, the Swedish chemist who invented dynamite, and first awarded in 1901. Prizes are given each year in physics, chemistry, physiology or medicine, literature and peace; a prize in economic sciences was added in 1969 by Sweden’s central bank. The peace prize is awarded in Oslo, Norway, and the others in Stockholm, Sweden. Winners receive a medal, a diploma and a share of about 11 million Swedish kronor. Marie Curie was the first woman to win, in 1903.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 178\" width=\"610\" height=\"178\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"46\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Physics</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text><rect x=\"310\" y=\"10\" width=\"290\" height=\"46\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Chemistry</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text><rect x=\"10\" y=\"66\" width=\"290\" height=\"46\" rx=\"10\" fill=\"#dc2626\" fill-opacity=\".2\" stroke=\"#dc2626\"/><text x=\"24\" y=\"94\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Physiology or Medicine</text><text x=\"24\" y=\"114\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text><rect x=\"310\" y=\"66\" width=\"290\" height=\"46\" rx=\"10\" fill=\"#7c3aed\" fill-opacity=\".2\" stroke=\"#7c3aed\"/><text x=\"324\" y=\"94\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Literature</text><text x=\"324\" y=\"114\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text><rect x=\"10\" y=\"122\" width=\"290\" height=\"46\" rx=\"10\" fill=\"#f59e0b\" fill-opacity=\".2\" stroke=\"#f59e0b\"/><text x=\"24\" y=\"150\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Peace</text><text x=\"24\" y=\"170\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text><rect x=\"310\" y=\"122\" width=\"290\" height=\"46\" rx=\"10\" fill=\"#64748b\" fill-opacity=\".2\" stroke=\"#64748b\"/><text x=\"324\" y=\"150\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Economic Sciences (from 1969)</text><text x=\"324\" y=\"170\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text></svg>","c":"The six prize categories"}]},"accelerators":{"t":"The Large Hadron Collider","c":"Particle accelerators speed up subatomic particles to nearly the speed of light and smash them together, letting physicists study the smallest building blocks of matter. The largest, CERN’s Large Hadron Collider near Geneva, is a ring 27 kilometres around, buried about 100 metres underground across the French–Swiss border. Its superconducting magnets are cooled to −271 °C, colder than outer space. In 2012 it discovered the Higgs boson. Smaller accelerators are used in hospitals to treat cancer and in industry. Figures are approximate.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 144\" width=\"620\" height=\"144\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><text x=\"190\" y=\"31\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">LHC ring</text><rect x=\"200\" y=\"12\" width=\"280.0\" height=\"28\" rx=\"5\" fill=\"#2563eb\"/><text x=\"488\" y=\"31\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">27 km around</text><text x=\"190\" y=\"71\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Tevatron (US, closed)</text><rect x=\"200\" y=\"52\" width=\"65.3\" height=\"28\" rx=\"5\" fill=\"#64748b\"/><text x=\"273.3333333333333\" y=\"71\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">6.3 km</text><text x=\"190\" y=\"111\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Distance across Paris</text><rect x=\"200\" y=\"92\" width=\"103.7\" height=\"28\" rx=\"5\" fill=\"#94a3b8\"/><text x=\"311.7037037037037\" y=\"111\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">about 10 km, for comparison</text></svg>","c":"How big the Large Hadron Collider is"}]},"neutrinos":{"t":"Ghostly neutrinos","c":"Neutrinos are tiny particles with no electric charge and almost no mass, produced in huge numbers by nuclear reactions in the Sun, in supernovae and in nuclear reactors. They interact so weakly with matter that most pass straight through the entire Earth without hitting anything; about 100 billion from the Sun pass through each square centimetre of your body every second. Detecting them requires enormous underground tanks of water or ice, such as IceCube at the South Pole. The discovery that they change type and have mass won the 2015 Nobel Prize. Simplified.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 200\" width=\"620\" height=\"200\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"200\" rx=\"10\" fill=\"#0b1026\"/><circle cx=\"80\" cy=\"100\" r=\"40\" fill=\"#facc15\"/><path d=\"M120,80L590,60\" stroke=\"#a78bfa\" stroke-width=\"1\" opacity=\".6\"/><path d=\"M120,88L590,76\" stroke=\"#a78bfa\" stroke-width=\"1\" opacity=\".6\"/><path d=\"M120,96L590,92\" stroke=\"#a78bfa\" stroke-width=\"1\" opacity=\".6\"/><path d=\"M120,104L590,108\" stroke=\"#a78bfa\" stroke-width=\"1\" opacity=\".6\"/><path d=\"M120,112L590,124\" stroke=\"#a78bfa\" stroke-width=\"1\" opacity=\".6\"/><path d=\"M120,120L590,140\" stroke=\"#a78bfa\" stroke-width=\"1\" opacity=\".6\"/><circle cx=\"300\" cy=\"100\" r=\"30\" fill=\"#60a5fa\"/><text x=\"340\" y=\"30\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#e2e8f0\" font-family=\"system-ui,sans-serif\">Trillions pass through your body every second</text><text x=\"300\" y=\"150\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"#e2e8f0\" font-family=\"system-ui,sans-serif\">Earth</text><text x=\"80\" y=\"160\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"#e2e8f0\" font-family=\"system-ui,sans-serif\">Sun</text><text x=\"470\" y=\"180\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"#c4b5fd\" font-family=\"system-ui,sans-serif\">Neutrinos fly straight through</text></svg>","c":"Neutrinos streaming from the Sun through Earth"}]},"dreams":{"t":"The stages of sleep","c":"Sleep is not a single state but cycles through stages about every 90 minutes. Light sleep leads into deeper sleep, when the body repairs itself and the brain consolidates memories, and then rapid eye movement, or REM, sleep, when the brain is very active and most vivid dreams happen, while the body is temporarily paralysed so we do not act them out. REM periods grow longer toward morning. Why we dream is still debated; ideas include processing emotions, strengthening memories and rehearsing responses to threats. Simplified.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 200\" width=\"620\" height=\"200\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"200\" rx=\"10\" fill=\"#f8fafc\"/><rect x=\"20\" y=\"130\" width=\"130\" height=\"40\" rx=\"6\" fill=\"#bfdbfe\"/><text x=\"85\" y=\"30\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Stage 1</text><text x=\"85\" y=\"48\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">light sleep</text><rect x=\"165\" y=\"90\" width=\"130\" height=\"80\" rx=\"6\" fill=\"#93c5fd\"/><text x=\"230\" y=\"30\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Stage 2</text><text x=\"230\" y=\"48\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">heart rate slows</text><rect x=\"310\" y=\"50\" width=\"130\" height=\"120\" rx=\"6\" fill=\"#2563eb\"/><text x=\"375\" y=\"30\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Stage 3</text><text x=\"375\" y=\"48\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">deep sleep</text><rect x=\"455\" y=\"110\" width=\"130\" height=\"60\" rx=\"6\" fill=\"#7c3aed\"/><text x=\"520\" y=\"30\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">REM</text><text x=\"520\" y=\"48\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">vivid dreams</text><text x=\"310\" y=\"192\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">One sleep cycle lasts about 90 minutes; most people have 4–6 a night</text></svg>","c":"The stages of one sleep cycle (bar height suggests depth)"}]},"ecommerce":{"t":"From click to doorstep","c":"Online shopping, or e-commerce, has grown enormously since the 1990s, and especially during the COVID-19 pandemic. When you order, the store’s systems process payment, a fulfilment warehouse, often heavily automated with robots, picks and packs the item, and delivery companies carry it through sorting hubs to your door or a pickup locker, sometimes the same day. E-commerce now makes up roughly a fifth of global retail sales. It brings convenience and choice but also raises concerns about packaging waste, delivery emissions and pressure on workers. Simplified.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 180\" width=\"620\" height=\"180\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"210\" rx=\"10\" fill=\"#f8fafc\"/><rect x=\"20\" y=\"70\" width=\"140\" height=\"70\" rx=\"10\" fill=\"#fde68a\"/><text x=\"90\" y=\"110\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">You buy online</text><path d=\"M160,105H182\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M190,105l-10,-6v12z\" fill=\"currentColor\"/><rect x=\"190\" y=\"70\" width=\"120\" height=\"70\" rx=\"10\" fill=\"#bfdbfe\"/><text x=\"250\" y=\"102\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Warehouse</text><text x=\"250\" y=\"120\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">picks and packs</text><path d=\"M310,105H332\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M340,105l-10,-6v12z\" fill=\"currentColor\"/><rect x=\"340\" y=\"70\" width=\"120\" height=\"70\" rx=\"10\" fill=\"#c7d2fe\"/><text x=\"400\" y=\"102\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Delivery</text><text x=\"400\" y=\"120\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">van, bike, drone</text><path d=\"M460,105H482\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M490,105l-10,-6v12z\" fill=\"currentColor\"/><rect x=\"490\" y=\"70\" width=\"120\" height=\"70\" rx=\"10\" fill=\"#bbf7d0\"/><text x=\"550\" y=\"102\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Your door</text><text x=\"550\" y=\"120\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">or a locker</text></svg>","c":"The journey of an online order"}]},"digitalpay":{"t":"How a digital payment works","c":"Digital payments let people pay with phones, cards and apps instead of cash. When you scan a QR code or tap your phone, a payment app or card network checks your identity and balance, then instructs banks to move money to the seller, usually within seconds. Countries such as India, with its UPI system, China, with Alipay and WeChat Pay, Kenya, with M-Pesa, and Sweden have become largely cashless in everyday shopping. Digital payments are convenient and can include people without bank accounts, but raise questions about privacy, scams and those without phones. Simplified.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 180\" width=\"620\" height=\"180\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"210\" rx=\"10\" fill=\"#f8fafc\"/><rect x=\"20\" y=\"70\" width=\"140\" height=\"70\" rx=\"10\" fill=\"#bfdbfe\"/><text x=\"90\" y=\"102\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Your phone</text><text x=\"90\" y=\"120\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">scan or tap</text><path d=\"M160,105H182\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M190,105l-10,-6v12z\" fill=\"currentColor\"/><rect x=\"190\" y=\"70\" width=\"130\" height=\"70\" rx=\"10\" fill=\"#fde68a\"/><text x=\"255\" y=\"102\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Payment app</text><text x=\"255\" y=\"120\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">checks and confirms</text><path d=\"M320,105H342\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M350,105l-10,-6v12z\" fill=\"currentColor\"/><rect x=\"350\" y=\"70\" width=\"120\" height=\"70\" rx=\"10\" fill=\"#c7d2fe\"/><text x=\"410\" y=\"102\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Banks</text><text x=\"410\" y=\"120\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">move the money</text><path d=\"M470,105H492\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M500,105l-10,-6v12z\" fill=\"currentColor\"/><rect x=\"500\" y=\"70\" width=\"110\" height=\"70\" rx=\"10\" fill=\"#bbf7d0\"/><text x=\"555\" y=\"102\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Seller</text><text x=\"555\" y=\"120\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">paid in seconds</text></svg>","c":"The steps behind a phone payment"}]},"covid19":{"t":"The COVID-19 pandemic","c":"COVID-19, caused by the SARS-CoV-2 coronavirus, was first identified in Wuhan, China, in late 2019 and spread worldwide within months. Governments closed borders, schools and businesses, and billions of people lived under lockdowns. Vaccines were developed in under a year, some using new mRNA technology, and over 13 billion doses were given. The World Health Organization estimated that the pandemic caused around 7 million reported deaths, with the true toll several times higher. It ended as a global emergency in May 2023.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 246\" width=\"640\" height=\"246\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"230\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Dec 2019</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">First cases identified in Wuhan, China</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Mar 2020</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">WHO declares a pandemic; lockdowns worldwide</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Dec 2020</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">First vaccines approved and rolled out</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">2021–22</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Delta and Omicron variants spread</text><circle cx=\"140\" cy=\"202\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"207\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">May 2023</text><text x=\"156\" y=\"207\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">WHO ends the global health emergency</text></svg>","c":"Key moments of the pandemic"}]},"vaping":{"t":"What is known about vaping","c":"E-cigarettes heat a liquid, usually containing nicotine and flavourings, into an aerosol that users inhale. Health authorities generally agree they are less harmful than smoking tobacco cigarettes and may help some adult smokers quit, but they are not harmless: nicotine is highly addictive and can harm the developing brains of teenagers, and the aerosol can contain harmful substances. Their long-term effects are still unknown. Youth vaping rose sharply in many countries, and governments have responded with age limits, flavour bans and taxes.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 170\" width=\"610\" height=\"170\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#dc2626\" fill-opacity=\".2\" stroke=\"#dc2626\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Nicotine</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Highly addictive; harms teen brains</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#f59e0b\" fill-opacity=\".2\" stroke=\"#f59e0b\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Lung irritation</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Aerosol can carry harmful chemicals</text><rect x=\"10\" y=\"90\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"24\" y=\"118\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Lower risk than smoking</text><text x=\"24\" y=\"138\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">For adult smokers who switch completely</text><rect x=\"310\" y=\"90\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#64748b\" fill-opacity=\".2\" stroke=\"#64748b\"/><text x=\"324\" y=\"118\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Unknown long-term effects</text><text x=\"324\" y=\"138\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Still being studied</text></svg>","c":"Main points health authorities make"}]},"nato":{"t":"NATO’s growth","c":"The North Atlantic Treaty Organization was founded in 1949 by the United States, Canada and ten Western European countries as a military alliance against the Soviet Union. Its core principle, Article 5, says an attack on one member is an attack on all; it has been invoked only once, after the 11 September 2001 attacks on the United States. After the Cold War, many former Eastern Bloc countries joined, and Finland and Sweden joined in 2023 and 2024 after Russia’s full-scale invasion of Ukraine, bringing membership to 32.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 246\" width=\"640\" height=\"246\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"230\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#1d4ed8\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1949</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">12 founding members</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#1d4ed8\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1952</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Greece and Turkey join</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#1d4ed8\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1955</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">West Germany joins</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#1d4ed8\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1999–2004</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Former Eastern Bloc countries join</text><circle cx=\"140\" cy=\"202\" r=\"8\" fill=\"#1d4ed8\"/><text x=\"126\" y=\"207\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">2023–24</text><text x=\"156\" y=\"207\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Finland and Sweden join (32 members)</text></svg>","c":"Milestones in NATO membership"}]},"education":{"t":"The stages of education","c":"Most education systems move through stages. Early childhood education prepares young children for school. Primary school teaches basic literacy, numeracy and other subjects; secondary school deepens these, often ending in exams or a diploma; and tertiary education includes universities, colleges and vocational training. Ages and names differ between countries. Around 250 million children and young people worldwide are still out of school, according to UNESCO, mostly in poorer and conflict-affected regions.","items":[{"w":1,"s":"<svg viewBox=\"0 0 600 220\" width=\"600\" height=\"220\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"580\" height=\"60\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Primary</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">About ages 6–11: reading, writing, maths</text><rect x=\"10\" y=\"80\" width=\"580\" height=\"60\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"24\" y=\"108\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Secondary</text><text x=\"24\" y=\"128\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">About ages 12–17: subjects and exams</text><rect x=\"10\" y=\"150\" width=\"580\" height=\"60\" rx=\"10\" fill=\"#7c3aed\" fill-opacity=\".2\" stroke=\"#7c3aed\"/><text x=\"24\" y=\"178\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Tertiary</text><text x=\"24\" y=\"198\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">University, college, vocational training</text></svg>","c":"Common stages of schooling"}]},"clothing":{"t":"Common fabric fibres","c":"Clothing is made from natural or synthetic fibres spun into yarn and woven or knitted into fabric. Natural fibres come from plants, such as cotton, linen and hemp, or animals, such as wool and silk. Synthetic fibres such as polyester and nylon, first developed in the 20th century, are made from chemicals derived mostly from oil and now account for over half of all fibre produced. Each has trade-offs in comfort, durability, cost and environmental impact, from the water used to grow cotton to the microplastics shed by synthetics.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 220\" width=\"610\" height=\"220\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"60\" rx=\"10\" fill=\"#94a3b8\" fill-opacity=\".2\" stroke=\"#94a3b8\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Cotton</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Plant fibre; soft and breathable</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"60\" rx=\"10\" fill=\"#ca8a04\" fill-opacity=\".2\" stroke=\"#ca8a04\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Wool</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Animal fibre; warm</text><rect x=\"10\" y=\"80\" width=\"290\" height=\"60\" rx=\"10\" fill=\"#db2777\" fill-opacity=\".2\" stroke=\"#db2777\"/><text x=\"24\" y=\"108\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Silk</text><text x=\"24\" y=\"128\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">From silkworms; smooth</text><rect x=\"310\" y=\"80\" width=\"290\" height=\"60\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"324\" y=\"108\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Polyester</text><text x=\"324\" y=\"128\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Made from oil; tough and cheap</text><rect x=\"10\" y=\"150\" width=\"290\" height=\"60\" rx=\"10\" fill=\"#a16207\" fill-opacity=\".2\" stroke=\"#a16207\"/><text x=\"24\" y=\"178\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Linen</text><text x=\"24\" y=\"198\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">From flax; cool</text><rect x=\"310\" y=\"150\" width=\"290\" height=\"60\" rx=\"10\" fill=\"#7c3aed\" fill-opacity=\".2\" stroke=\"#7c3aed\"/><text x=\"324\" y=\"178\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Nylon</text><text x=\"324\" y=\"198\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Synthetic; strong and stretchy</text></svg>","c":"Six common fibres and their traits"}]},"amazonriver":{"t":"The Amazon carries the most water","c":"The Amazon is the largest river in the world by the amount of water it carries, discharging on average about 200,000 cubic metres every second into the Atlantic, roughly a fifth of all the fresh water that rivers deliver to the oceans and more than the next several largest rivers combined. Its basin, covering about 7 million square kilometres across nine South American countries, holds the largest rainforest on Earth. Whether it or the Nile is the longest river depends on how lengths are measured. Figures are approximate average discharges.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 264\" width=\"620\" height=\"264\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><text x=\"180\" y=\"31\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Amazon</text><rect x=\"190\" y=\"12\" width=\"280.0\" height=\"28\" rx=\"5\" fill=\"#16a34a\"/><text x=\"478\" y=\"31\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">about 209,000 m³/s</text><text x=\"180\" y=\"71\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Congo</text><rect x=\"190\" y=\"52\" width=\"54.9\" height=\"28\" rx=\"5\" fill=\"#a16207\"/><text x=\"252.92822966507177\" y=\"71\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">about 41,000</text><text x=\"180\" y=\"111\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Ganges–Brahmaputra</text><rect x=\"190\" y=\"92\" width=\"50.9\" height=\"28\" rx=\"5\" fill=\"#f59e0b\"/><text x=\"248.9090909090909\" y=\"111\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">about 38,000</text><text x=\"180\" y=\"151\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Orinoco</text><rect x=\"190\" y=\"132\" width=\"49.6\" height=\"28\" rx=\"5\" fill=\"#0891b2\"/><text x=\"247.5693779904306\" y=\"151\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">about 37,000</text><text x=\"180\" y=\"191\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Yangtze</text><rect x=\"190\" y=\"172\" width=\"41.5\" height=\"28\" rx=\"5\" fill=\"#2563eb\"/><text x=\"239.5311004784689\" y=\"191\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">about 31,000</text><text x=\"180\" y=\"231\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Nile</text><rect x=\"190\" y=\"212\" width=\"4.0\" height=\"28\" rx=\"5\" fill=\"#94a3b8\"/><text x=\"202\" y=\"231\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">about 2,800</text></svg>","c":"Approximate average water flow at the river mouth"}]},"yangtze":{"t":"The Yangtze from source to sea","c":"The Yangtze, about 6,300 kilometres long, is the longest river in Asia and the third-longest in the world. It rises on the Tibetan Plateau and flows east across China to reach the East China Sea at Shanghai. Its basin is home to roughly a third of China’s population and produces much of its rice. The Three Gorges Dam, completed in 2006, is the world’s largest power station by capacity, though its construction displaced over a million people. Schematic, not a map.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 200\" width=\"620\" height=\"200\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"200\" rx=\"10\" fill=\"#e0f2fe\"/><path d=\"M20,30Q180,60 260,100T600,170\" fill=\"none\" stroke=\"#2563eb\" stroke-width=\"12\"/><circle cx=\"30\" cy=\"30\" r=\"8\" fill=\"#f59e0b\" stroke=\"#fff\" stroke-width=\"2\"/><text x=\"30\" y=\"16\" text-anchor=\"start\" font-size=\"12\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Tibetan Plateau</text><circle cx=\"260\" cy=\"100\" r=\"8\" fill=\"#f59e0b\" stroke=\"#fff\" stroke-width=\"2\"/><text x=\"260\" y=\"86\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Three Gorges Dam</text><circle cx=\"380\" cy=\"130\" r=\"8\" fill=\"#f59e0b\" stroke=\"#fff\" stroke-width=\"2\"/><text x=\"380\" y=\"116\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Wuhan</text><circle cx=\"590\" cy=\"168\" r=\"8\" fill=\"#f59e0b\" stroke=\"#fff\" stroke-width=\"2\"/><text x=\"590\" y=\"154\" text-anchor=\"end\" font-size=\"12\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Shanghai</text><text x=\"310\" y=\"192\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">About 6,300 km long: Asia’s longest river</text></svg>","c":"The Yangtze’s course (schematic)"}]},"ganges":{"t":"The Ganges","c":"The Ganges, or Ganga, flows about 2,500 kilometres from the Gangotri Glacier in the Himalayas across northern India to the Bay of Bengal, where, joined by the Brahmaputra, it forms the world’s largest delta in Bangladesh and India. The river is sacred in Hinduism, and millions bathe in it at holy cities such as Varanasi and at the Kumbh Mela festival. Its plain is one of the most densely populated regions on Earth. Pollution is a serious problem, and clean-up programmes are under way. Schematic.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 200\" width=\"620\" height=\"200\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"200\" rx=\"10\" fill=\"#fef3c7\"/><path d=\"M30,40Q160,70 260,100T590,160\" fill=\"none\" stroke=\"#0891b2\" stroke-width=\"12\"/><circle cx=\"30\" cy=\"40\" r=\"8\" fill=\"#ea580c\" stroke=\"#fff\" stroke-width=\"2\"/><text x=\"30\" y=\"26\" text-anchor=\"start\" font-size=\"12\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Himalayan glacier</text><circle cx=\"300\" cy=\"108\" r=\"8\" fill=\"#ea580c\" stroke=\"#fff\" stroke-width=\"2\"/><text x=\"300\" y=\"94\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Varanasi</text><circle cx=\"590\" cy=\"160\" r=\"8\" fill=\"#ea580c\" stroke=\"#fff\" stroke-width=\"2\"/><text x=\"590\" y=\"146\" text-anchor=\"end\" font-size=\"12\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Delta in Bangladesh</text><text x=\"310\" y=\"192\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Sacred in Hinduism; supports about 400 million people</text></svg>","c":"The Ganges from the Himalayas to the delta (schematic)"}]},"danube":{"t":"The Danube through ten countries","c":"The Danube, Europe’s second-longest river after the Volga at about 2,850 kilometres, flows from Germany’s Black Forest to the Black Sea, passing through or along the borders of ten countries, more than any other river in the world. Four capital cities stand on its banks: Vienna, Bratislava, Budapest and Belgrade. For centuries it has been a vital trade route and, at times, a frontier, such as the northern border of the Roman Empire. Its delta in Romania and Ukraine is a haven for birds. Schematic.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 160\" width=\"620\" height=\"160\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"160\" rx=\"10\" fill=\"#f8fafc\"/><path d=\"M20,80Q150,50 300,90T600,70\" fill=\"none\" stroke=\"#2563eb\" stroke-width=\"10\"/><circle cx=\"40\" cy=\"80.0\" r=\"6\" fill=\"#f59e0b\"/><text x=\"40\" y=\"44\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Germany</text><circle cx=\"100\" cy=\"88.7\" r=\"6\" fill=\"#f59e0b\"/><text x=\"100\" y=\"130\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Austria</text><circle cx=\"160\" cy=\"93.6\" r=\"6\" fill=\"#f59e0b\"/><text x=\"160\" y=\"44\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Slovakia</text><circle cx=\"220\" cy=\"92.7\" r=\"6\" fill=\"#f59e0b\"/><text x=\"220\" y=\"130\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Hungary</text><circle cx=\"280\" cy=\"86.4\" r=\"6\" fill=\"#f59e0b\"/><text x=\"280\" y=\"44\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Croatia</text><circle cx=\"340\" cy=\"77.3\" r=\"6\" fill=\"#f59e0b\"/><text x=\"340\" y=\"130\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Serbia</text><circle cx=\"400\" cy=\"69.4\" r=\"6\" fill=\"#f59e0b\"/><text x=\"400\" y=\"44\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Romania</text><circle cx=\"460\" cy=\"66.0\" r=\"6\" fill=\"#f59e0b\"/><text x=\"460\" y=\"130\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Bulgaria</text><circle cx=\"520\" cy=\"68.6\" r=\"6\" fill=\"#f59e0b\"/><text x=\"520\" y=\"44\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Moldova</text><circle cx=\"580\" cy=\"76.1\" r=\"6\" fill=\"#f59e0b\"/><text x=\"580\" y=\"130\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Ukraine</text></svg>","c":"Countries along the Danube, west to east (schematic)"}]},"mississippi":{"t":"The Mississippi river system","c":"The Mississippi flows about 3,700 kilometres from Lake Itasca in Minnesota to the Gulf of Mexico. Together with its great tributary the Missouri, it forms one of the longest river systems in the world, draining all or part of 31 US states and two Canadian provinces, about 40 percent of the continental United States. It has long been a highway for trade, from Native American canoes to steamboats celebrated by Mark Twain to today’s barges, and its fertile floodplain grows huge harvests. Schematic, not a map.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 200\" width=\"620\" height=\"200\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"200\" rx=\"10\" fill=\"#f8fafc\"/><path d=\"M300,10V190\" stroke=\"#2563eb\" stroke-width=\"12\"/><path d=\"M60,60Q180,70 300,90M560,40Q430,70 300,110\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"7\"/><text x=\"100\" y=\"50\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Missouri</text><text x=\"520\" y=\"34\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Ohio</text><text x=\"310\" y=\"184\" text-anchor=\"start\" font-size=\"12\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Gulf of Mexico</text><text x=\"310\" y=\"30\" text-anchor=\"start\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Mississippi</text></svg>","c":"The Mississippi and two major tributaries (schematic)"}]},"madag":{"t":"Found nowhere else","c":"Madagascar, the world’s fourth-largest island, split from Africa about 160 million years ago and from India around 88 million years ago. Its plants and animals evolved in isolation, so a remarkably high share are found nowhere else on Earth: all its lemurs, most of its reptiles and amphibians, and the large majority of its plant species, including six of the world’s eight baobab species. Much of its original forest has been lost, putting many unique species at risk. Percentages are commonly cited estimates of endemic species.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 224\" width=\"620\" height=\"224\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><text x=\"120\" y=\"31\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Lemurs</text><rect x=\"130\" y=\"12\" width=\"340.0\" height=\"28\" rx=\"5\" fill=\"#a16207\"/><text x=\"478\" y=\"31\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">100%</text><text x=\"120\" y=\"71\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Amphibians</text><rect x=\"130\" y=\"52\" width=\"336.6\" height=\"28\" rx=\"5\" fill=\"#16a34a\"/><text x=\"474.6\" y=\"71\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">about 99%</text><text x=\"120\" y=\"111\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Reptiles</text><rect x=\"130\" y=\"92\" width=\"306.0\" height=\"28\" rx=\"5\" fill=\"#65a30d\"/><text x=\"444\" y=\"111\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">about 90%</text><text x=\"120\" y=\"151\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Plants</text><rect x=\"130\" y=\"132\" width=\"272.0\" height=\"28\" rx=\"5\" fill=\"#22c55e\"/><text x=\"410\" y=\"151\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">about 80%</text><text x=\"120\" y=\"191\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Birds</text><rect x=\"130\" y=\"172\" width=\"170.0\" height=\"28\" rx=\"5\" fill=\"#2563eb\"/><text x=\"308\" y=\"191\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">about 50%</text></svg>","c":"Share of species found only on Madagascar (approximate)"}]},"med":{"t":"A sea between three continents","c":"The Mediterranean, about 2.5 million square kilometres, lies almost enclosed between Europe, Africa and Asia, linked to the Atlantic only by the Strait of Gibraltar, just 14 kilometres wide at its narrowest. Its name means ‘middle of the land’. It was the crossroads of many ancient civilisations, from Egypt, Phoenicia, Greece and Rome to the Byzantines, Arabs and Ottomans. Today its coasts are home to over 20 countries. Because rivers and rain cannot replace what evaporates, it is saltier than the Atlantic. Schematic.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 200\" width=\"620\" height=\"200\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"200\" rx=\"10\" fill=\"#fef3c7\"/><path d=\"M20,150Q160,140 300,150T600,140V200H20Z\" fill=\"#38bdf8\"/><path d=\"M20,150Q160,140 300,150T600,140\" fill=\"none\" stroke=\"#0284c7\" stroke-width=\"3\"/><text x=\"150\" y=\"60\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"900\" fill=\"#78350f\" font-family=\"system-ui,sans-serif\">Europe</text><text x=\"520\" y=\"60\" text-anchor=\"middle\" font-size=\"16\" font-weight=\"900\" fill=\"#78350f\" font-family=\"system-ui,sans-serif\">Asia</text><text x=\"310\" y=\"194\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"900\" fill=\"#fff\" font-family=\"system-ui,sans-serif\">Africa (south shore)</text><text x=\"310\" y=\"172\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#fff\" font-family=\"system-ui,sans-serif\">Mediterranean Sea</text><text x=\"40\" y=\"130\" text-anchor=\"start\" font-size=\"11\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Strait of Gibraltar: only 14 km wide</text></svg>","c":"The Mediterranean between three continents (schematic)"}]},"sea":{"t":"The countries of Southeast Asia","c":"Southeast Asia is made up of 11 countries between China, India and Australia: mainland nations along the Mekong and great island nations scattered across seas, including Indonesia, the largest archipelago in the world, and the Philippines. About 680 million people live there, speaking hundreds of languages and following Buddhism, Islam, Christianity, Hinduism and local beliefs. Ten are members of ASEAN, and Timor-Leste is joining. The region’s history was shaped by Indian and Chinese influence, trade, empires such as Srivijaya and the Khmer, and colonial rule.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 226\" width=\"610\" height=\"226\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"190\" height=\"44\" rx=\"10\" fill=\"#dc2626\" fill-opacity=\".2\" stroke=\"#dc2626\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Brunei</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text><rect x=\"210\" y=\"10\" width=\"190\" height=\"44\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"224\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Cambodia</text><text x=\"224\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text><rect x=\"410\" y=\"10\" width=\"190\" height=\"44\" rx=\"10\" fill=\"#f59e0b\" fill-opacity=\".2\" stroke=\"#f59e0b\"/><text x=\"424\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Indonesia</text><text x=\"424\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text><rect x=\"10\" y=\"64\" width=\"190\" height=\"44\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"24\" y=\"92\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Laos</text><text x=\"24\" y=\"112\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text><rect x=\"210\" y=\"64\" width=\"190\" height=\"44\" rx=\"10\" fill=\"#7c3aed\" fill-opacity=\".2\" stroke=\"#7c3aed\"/><text x=\"224\" y=\"92\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Malaysia</text><text x=\"224\" y=\"112\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text><rect x=\"410\" y=\"64\" width=\"190\" height=\"44\" rx=\"10\" fill=\"#0891b2\" fill-opacity=\".2\" stroke=\"#0891b2\"/><text x=\"424\" y=\"92\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Myanmar</text><text x=\"424\" y=\"112\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text><rect x=\"10\" y=\"118\" width=\"190\" height=\"44\" rx=\"10\" fill=\"#dc2626\" fill-opacity=\".2\" stroke=\"#dc2626\"/><text x=\"24\" y=\"146\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Philippines</text><text x=\"24\" y=\"166\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text><rect x=\"210\" y=\"118\" width=\"190\" height=\"44\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"224\" y=\"146\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Singapore</text><text x=\"224\" y=\"166\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text><rect x=\"410\" y=\"118\" width=\"190\" height=\"44\" rx=\"10\" fill=\"#f59e0b\" fill-opacity=\".2\" stroke=\"#f59e0b\"/><text x=\"424\" y=\"146\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Thailand</text><text x=\"424\" y=\"166\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text><rect x=\"10\" y=\"172\" width=\"190\" height=\"44\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"24\" y=\"200\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Timor-Leste</text><text x=\"24\" y=\"220\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text><rect x=\"210\" y=\"172\" width=\"190\" height=\"44\" rx=\"10\" fill=\"#7c3aed\" fill-opacity=\".2\" stroke=\"#7c3aed\"/><text x=\"224\" y=\"200\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Vietnam</text><text x=\"224\" y=\"220\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text></svg>","c":"The 11 countries of Southeast Asia"}]},"hawaii":{"t":"How a hot spot built Hawaii","c":"The Hawaiian Islands sit in the middle of the Pacific Plate, far from any plate boundary. Beneath them, a plume of hot rock rising from deep in the mantle, called a hot spot, melts through the crust and builds volcanoes. As the plate slowly drifts northwest, about 7 centimetres a year, each volcano is carried away from the hot spot and goes extinct, while a new one forms. That is why the islands get older to the northwest and why the Big Island, still over the hot spot, has active volcanoes such as Kīlauea. Simplified cross-section.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 200\" width=\"620\" height=\"200\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"200\" rx=\"10\" fill=\"#bae6fd\"/><path d=\"M0,140H620V200H0Z\" fill=\"#0284c7\"/><path d=\"M440,140L500,100L560,140Z\" fill=\"#16a34a\"/><text x=\"500\" y=\"90\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Older, worn-down islands</text><path d=\"M340,140L400,80L460,140Z\" fill=\"#22c55e\"/><path d=\"M240,140L300,60L360,140Z\" fill=\"#65a30d\"/><path d=\"M90,140L150,40L210,140Z\" fill=\"#78716c\"/><text x=\"150\" y=\"30\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Youngest island over the hot spot</text><path d=\"M150,200V150\" stroke=\"#dc2626\" stroke-width=\"10\"/><ellipse cx=\"150\" cy=\"200\" rx=\"40\" ry=\"10\" fill=\"#dc2626\"/><text x=\"150\" y=\"190\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"#fff\" font-family=\"system-ui,sans-serif\">Hot spot</text><path d=\"M560,180H420\" stroke=\"#fff\" stroke-width=\"3\"/><path d=\"M410,180l12,-6v12z\" fill=\"#fff\"/><text x=\"490\" y=\"172\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"800\" fill=\"#fff\" font-family=\"system-ui,sans-serif\">Pacific Plate moves</text></svg>","c":"A chain of volcanoes over a hot spot"}]},"galapagos":{"t":"Wildlife of the Galápagos","c":"The Galápagos Islands, about 1,000 kilometres off the coast of Ecuador, are volcanic islands where many animals evolved in isolation. Giant tortoises differ in shell shape from island to island, marine iguanas dive to graze on seaweed, and the islands host the only penguins that live at the equator. Charles Darwin’s visit in 1835 helped inspire his theory of evolution by natural selection. The islands are a national park and UNESCO World Heritage Site, and visitor numbers are strictly controlled.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 170\" width=\"610\" height=\"170\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#57534e\" fill-opacity=\".2\" stroke=\"#57534e\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Giant tortoises</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Each island’s shell shape differs</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#475569\" fill-opacity=\".2\" stroke=\"#475569\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Marine iguanas</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">The only lizards that feed in the sea</text><rect x=\"10\" y=\"90\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"24\" y=\"118\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Blue-footed boobies</text><text x=\"24\" y=\"138\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Dance to show off their feet</text><rect x=\"310\" y=\"90\" width=\"290\" height=\"70\" rx=\"10\" fill=\"#a16207\" fill-opacity=\".2\" stroke=\"#a16207\"/><text x=\"324\" y=\"118\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Darwin’s finches</text><text x=\"324\" y=\"138\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Beaks suited to different foods</text></svg>","c":"Four famous Galápagos animals"}]},"greenland":{"t":"The world’s largest islands","c":"Greenland is the world’s largest island, about 2.2 million square kilometres, though around four-fifths of it lies under an ice sheet up to 3 kilometres thick. Only about 57,000 people live there, mostly Inuit, along the ice-free coasts. It is a self-governing territory within the Kingdom of Denmark. Australia is larger but is counted as a continent. If Greenland’s ice melted entirely, global sea levels would rise by about 7 metres. Areas are approximate.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 224\" width=\"620\" height=\"224\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><text x=\"160\" y=\"31\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Greenland</text><rect x=\"170\" y=\"12\" width=\"300.0\" height=\"28\" rx=\"5\" fill=\"#94a3b8\"/><text x=\"478\" y=\"31\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">2,166 thousand km²</text><text x=\"160\" y=\"71\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">New Guinea</text><rect x=\"170\" y=\"52\" width=\"108.9\" height=\"28\" rx=\"5\" fill=\"#16a34a\"/><text x=\"286.86426592797784\" y=\"71\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">786 thousand km²</text><text x=\"160\" y=\"111\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Borneo</text><rect x=\"170\" y=\"92\" width=\"103.6\" height=\"28\" rx=\"5\" fill=\"#65a30d\"/><text x=\"281.60110803324096\" y=\"111\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">748 thousand km²</text><text x=\"160\" y=\"151\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Madagascar</text><rect x=\"170\" y=\"132\" width=\"81.3\" height=\"28\" rx=\"5\" fill=\"#a16207\"/><text x=\"259.30193905817174\" y=\"151\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">587 thousand km²</text><text x=\"160\" y=\"191\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Baffin Island</text><rect x=\"170\" y=\"172\" width=\"70.2\" height=\"28\" rx=\"5\" fill=\"#64748b\"/><text x=\"248.22160664819944\" y=\"191\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">507 thousand km²</text></svg>","c":"Areas of the largest islands (excluding Australia)"}]},"borneo":{"t":"One island, three countries","c":"Borneo, the third-largest island in the world, is shared by three countries: Indonesia’s Kalimantan covers most of the south, Malaysia’s states of Sabah and Sarawak lie in the north, and the small sultanate of Brunei sits on the northern coast. Its ancient rainforests are among the most biodiverse on Earth, home to orangutans, pygmy elephants, proboscis monkeys and the giant Rafflesia flower, but large areas have been cleared for logging and palm oil plantations. Shares of land area are approximate.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 144\" width=\"620\" height=\"144\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><text x=\"200\" y=\"31\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Indonesia (Kalimantan)</text><rect x=\"210\" y=\"12\" width=\"260.0\" height=\"28\" rx=\"5\" fill=\"#dc2626\"/><text x=\"478\" y=\"31\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">about 73%</text><text x=\"200\" y=\"71\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Malaysia (Sabah, Sarawak)</text><rect x=\"210\" y=\"52\" width=\"92.6\" height=\"28\" rx=\"5\" fill=\"#2563eb\"/><text x=\"310.6027397260274\" y=\"71\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">about 26%</text><text x=\"200\" y=\"111\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Brunei</text><rect x=\"210\" y=\"92\" width=\"4.0\" height=\"28\" rx=\"5\" fill=\"#f59e0b\"/><text x=\"222\" y=\"111\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">about 1%</text></svg>","c":"Share of Borneo’s land area by country"}]},"sahel":{"t":"The Sahel: a transition zone","c":"The Sahel is a belt of semi-arid land stretching about 5,000 kilometres across Africa, from Senegal on the Atlantic to Sudan and Eritrea on the Red Sea, between the Sahara Desert to the north and wetter savannas to the south. Its name comes from the Arabic for ‘shore’ or ‘edge’. Rain falls only in a short wet season, so droughts can be devastating, as in the famines of the 1970s and 1980s. The Great Green Wall initiative aims to restore degraded land across the region. Schematic.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 190\" width=\"620\" height=\"190\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"200\" rx=\"10\" fill=\"#fef3c7\"/><rect x=\"0\" y=\"20\" width=\"620\" height=\"50\" fill=\"#fde68a\"/><rect x=\"0\" y=\"70\" width=\"620\" height=\"60\" fill=\"#d9f99d\"/><rect x=\"0\" y=\"130\" width=\"620\" height=\"50\" fill=\"#86efac\"/><text x=\"310\" y=\"50\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"800\" fill=\"#78350f\" font-family=\"system-ui,sans-serif\">Sahara Desert (north)</text><text x=\"310\" y=\"104\" text-anchor=\"middle\" font-size=\"15\" font-weight=\"900\" fill=\"#365314\" font-family=\"system-ui,sans-serif\">Sahel: semi-arid grassland</text><text x=\"310\" y=\"160\" text-anchor=\"middle\" font-size=\"14\" font-weight=\"800\" fill=\"#14532d\" font-family=\"system-ui,sans-serif\">Savanna (south)</text></svg>","c":"The Sahel between desert and savanna (schematic)"}]},"patagonia":{"t":"Patagonia’s two faces","c":"Patagonia is the vast region at the southern tip of South America, shared by Argentina and Chile. In the west, the Andes rise in jagged granite peaks such as Fitz Roy and the Torres del Paine, with huge ice fields and glaciers, fjords and rainforests. To the east, in the rain shadow of the mountains, stretch windswept dry steppes grazed by sheep and guanacos. It is one of the least densely populated places on Earth. The name may come from the Patagones, giants said by Magellan’s crew to live there. Schematic.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 200\" width=\"620\" height=\"200\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"200\" rx=\"10\" fill=\"#e0f2fe\"/><path d=\"M0,200L120,60L180,120L260,30L340,140L620,150V200Z\" fill=\"#78716c\"/><path d=\"M240,58L260,30L280,58Z\" fill=\"#f8fafc\"/><path d=\"M340,140L620,150V200H340Z\" fill=\"#fde68a\"/><text x=\"180\" y=\"180\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"#fff\" font-family=\"system-ui,sans-serif\">Andes and glaciers (west)</text><text x=\"480\" y=\"180\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"#78350f\" font-family=\"system-ui,sans-serif\">Dry steppe (east)</text><text x=\"260\" y=\"22\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Fitz Roy, Torres del Paine</text></svg>","c":"From the Andes in the west to the steppe in the east (schematic)"}]},"polynesia":{"t":"The Polynesian Triangle","c":"Polynesia covers a vast triangle of the Pacific Ocean with corners at Hawaii, New Zealand and Easter Island, an area bigger than all of Africa, mostly open water. Beginning over 3,000 years ago, Polynesian navigators settled almost every habitable island within it in double-hulled voyaging canoes, finding their way without instruments by reading stars, swells, winds, clouds and birds. It was one of the greatest feats of exploration in human history. Today Polynesian cultures share related languages, traditions and a strong connection to the sea. Schematic.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 280\" width=\"620\" height=\"280\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:560px;max-width:100%;height:auto\"><rect width=\"620\" height=\"280\" rx=\"10\" fill=\"#0284c7\"/><path d=\"M310,40L130,240L500,230Z\" fill=\"none\" stroke=\"#bae6fd\" stroke-width=\"3\" stroke-dasharray=\"7 5\"/><circle cx=\"310\" cy=\"40\" r=\"9\" fill=\"#facc15\"/><text x=\"310\" y=\"26\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#fff\" font-family=\"system-ui,sans-serif\">Hawaiʻi</text><circle cx=\"130\" cy=\"240\" r=\"9\" fill=\"#facc15\"/><text x=\"130\" y=\"264\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#fff\" font-family=\"system-ui,sans-serif\">Aotearoa (New Zealand)</text><circle cx=\"500\" cy=\"230\" r=\"9\" fill=\"#facc15\"/><text x=\"500\" y=\"254\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#fff\" font-family=\"system-ui,sans-serif\">Rapa Nui (Easter Island)</text><text x=\"330\" y=\"170\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"#e0f2fe\" font-family=\"system-ui,sans-serif\">Samoa, Tonga, Tahiti, Cook Islands and more lie inside</text></svg>","c":"The corners of the Polynesian Triangle (schematic)"}]},"lagos":{"t":"Africa’s largest cities","c":"Lagos, Nigeria’s commercial capital on the Atlantic coast, is one of the largest and fastest-growing cities in Africa, with an estimated 15 to 20 million or more people in its metropolitan area. It is the heart of Nigeria’s economy and of Nollywood, one of the world’s biggest film industries, and of Afrobeats music. Africa is the fastest-urbanising continent, and several of its cities are expected to be among the world’s largest by mid-century. City population estimates vary widely between sources; figures here are approximate.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 264\" width=\"620\" height=\"264\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><text x=\"150\" y=\"31\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Cairo</text><rect x=\"160\" y=\"12\" width=\"310.0\" height=\"28\" rx=\"5\" fill=\"#a16207\"/><text x=\"478\" y=\"31\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">22 million</text><text x=\"150\" y=\"71\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Kinshasa</text><rect x=\"160\" y=\"52\" width=\"239.5\" height=\"28\" rx=\"5\" fill=\"#2563eb\"/><text x=\"407.5454545454545\" y=\"71\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">17 million</text><text x=\"150\" y=\"111\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Lagos</text><rect x=\"160\" y=\"92\" width=\"225.5\" height=\"28\" rx=\"5\" fill=\"#16a34a\"/><text x=\"393.4545454545455\" y=\"111\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">16 million</text><text x=\"150\" y=\"151\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Luanda</text><rect x=\"160\" y=\"132\" width=\"126.8\" height=\"28\" rx=\"5\" fill=\"#dc2626\"/><text x=\"294.8181818181818\" y=\"151\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">9 million</text><text x=\"150\" y=\"191\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Johannesburg</text><rect x=\"160\" y=\"172\" width=\"90.2\" height=\"28\" rx=\"5\" fill=\"#f59e0b\"/><text x=\"258.1818181818182\" y=\"191\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">6.4 million</text><text x=\"150\" y=\"231\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Nairobi</text><rect x=\"160\" y=\"212\" width=\"74.7\" height=\"28\" rx=\"5\" fill=\"#7c3aed\"/><text x=\"242.6818181818182\" y=\"231\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">5.3 million</text></svg>","c":"Approximate metropolitan populations, early 2020s"}]},"mexicocity":{"t":"A city on a drained lake","c":"Mexico City, one of the largest cities in the Americas with over 20 million people in its metropolitan area, stands in a high valley about 2,240 metres above sea level, on the site of the Aztec capital Tenochtitlan. The lakes that once filled the valley were drained after the Spanish conquest, and today the city pumps so much water from the soft clay beneath it that parts are sinking, in some places by tens of centimetres a year, tilting buildings and cracking pipes. Its historic centre is a UNESCO World Heritage Site. Simplified.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 220\" width=\"620\" height=\"220\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"220\" rx=\"10\" fill=\"#fef3c7\"/><path d=\"M0,220V160Q150,170 310,160T620,170V220Z\" fill=\"#a16207\"/><ellipse cx=\"310\" cy=\"150\" rx=\"250\" ry=\"40\" fill=\"#bae6fd\" opacity=\".7\"/><rect x=\"200\" y=\"80\" width=\"40\" height=\"60\" fill=\"#78716c\"/><rect x=\"250\" y=\"60\" width=\"50\" height=\"80\" fill=\"#a8a29e\"/><rect x=\"310\" y=\"90\" width=\"60\" height=\"50\" fill=\"#78716c\"/><text x=\"310\" y=\"30\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Mexico City sits on a former lake bed, about 2,240 m up</text><text x=\"310\" y=\"206\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"#fef3c7\" font-family=\"system-ui,sans-serif\">The soft clay is sinking up to tens of cm a year in places</text></svg>","c":"Mexico City on its old lake bed (simplified)"}]},"saopaulo":{"t":"São Paulo’s growth","c":"São Paulo is the largest city in Brazil and in the Southern Hemisphere, with over 22 million people in its metropolitan area. Founded by Jesuit missionaries in 1554, it grew rich in the 19th century on coffee and then on industry. Millions of immigrants arrived, especially from Italy, Portugal, Spain, Lebanon and Japan; it is home to the largest Japanese community outside Japan. Today it is Brazil’s financial centre, a sprawling city of skyscrapers famous for its food, culture and traffic jams.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 204\" width=\"640\" height=\"204\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"188\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#16a34a\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1554</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">São Paulo founded by Jesuit missionaries</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#16a34a\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1800s</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Coffee boom brings wealth and immigrants</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#16a34a\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Early 1900s</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Large Italian, Japanese and other immigration</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#16a34a\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Today</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Over 22 million people in the metropolitan area</text></svg>","c":"Milestones in São Paulo’s history"}]},"centralasia":{"t":"The five Central Asian republics","c":"Central Asia is usually taken to mean five countries that became independent when the Soviet Union broke up in 1991: Kazakhstan, Kyrgyzstan, Tajikistan, Turkmenistan and Uzbekistan. Their names share the Persian ending ‘-stan’, meaning ‘land of’. The region, a crossroads of the Silk Road, includes vast steppes, deserts and the Tian Shan and Pamir mountains, and ancient cities such as Samarkand and Bukhara. Kazakhstan, the world’s largest landlocked country, is bigger than Western Europe.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 118\" width=\"610\" height=\"118\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"190\" height=\"44\" rx=\"10\" fill=\"#0891b2\" fill-opacity=\".2\" stroke=\"#0891b2\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Kazakhstan</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text><rect x=\"210\" y=\"10\" width=\"190\" height=\"44\" rx=\"10\" fill=\"#dc2626\" fill-opacity=\".2\" stroke=\"#dc2626\"/><text x=\"224\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Kyrgyzstan</text><text x=\"224\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text><rect x=\"410\" y=\"10\" width=\"190\" height=\"44\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"424\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Tajikistan</text><text x=\"424\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text><rect x=\"10\" y=\"64\" width=\"190\" height=\"44\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"24\" y=\"92\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Turkmenistan</text><text x=\"24\" y=\"112\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text><rect x=\"210\" y=\"64\" width=\"190\" height=\"44\" rx=\"10\" fill=\"#7c3aed\" fill-opacity=\".2\" stroke=\"#7c3aed\"/><text x=\"224\" y=\"92\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Uzbekistan</text><text x=\"224\" y=\"112\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text></svg>","c":"The five republics"}]},"carabao":{"t":"The carabao","c":"The carabao is a domestic swamp-type water buffalo and the national animal of the Philippines. For centuries it has pulled ploughs through flooded rice fields, hauled carts and provided milk, meat and hides, earning it the title of the Filipino farmer’s best friend. Because it has few sweat glands, it wallows in mud and water to keep cool. Water buffalo were domesticated in Asia thousands of years ago, and similar swamp buffalo are used across Southeast Asia and southern China. Simplified.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 210\" width=\"620\" height=\"210\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"210\" rx=\"10\" fill=\"#ecfccb\"/><path d=\"M120,140Q130,80 240,80Q380,80 420,120L430,150Z\" fill=\"#475569\"/><circle cx=\"440\" cy=\"110\" r=\"30\" fill=\"#475569\"/><path d=\"M420,90Q380,40 330,60M460,90Q500,40 550,60\" fill=\"none\" stroke=\"#1c1917\" stroke-width=\"10\" stroke-linecap=\"round\"/><rect x=\"150\" y=\"140\" width=\"16\" height=\"50\" fill=\"#475569\"/><rect x=\"200\" y=\"140\" width=\"16\" height=\"50\" fill=\"#475569\"/><rect x=\"350\" y=\"140\" width=\"16\" height=\"50\" fill=\"#475569\"/><rect x=\"400\" y=\"140\" width=\"16\" height=\"50\" fill=\"#475569\"/><rect y=\"190\" width=\"620\" height=\"20\" fill=\"#65a30d\"/><text x=\"440\" y=\"40\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Huge swept-back horns</text><text x=\"250\" y=\"74\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Wallows in mud to stay cool</text></svg>","c":"A carabao, simplified"}]},"tamaraw":{"t":"The tamaraw","c":"The tamaraw is a small, stocky wild buffalo found only on the island of Mindoro in the Philippines. Unlike the domestic carabao, it is wild, shy and mostly active at night, with short, straight horns pointing up in a V shape. It once roamed across the island, but hunting, disease brought by cattle and the loss of its grassland and forest habitat reduced it to a few hundred animals. It is critically endangered, with recent counts finding around 600 in Mounts Iglit–Baco Natural Park and a few other sites. Simplified.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 210\" width=\"620\" height=\"210\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"210\" rx=\"10\" fill=\"#ecfccb\"/><path d=\"M140,140Q150,90 260,90Q380,90 410,120L420,150Z\" fill=\"#1c1917\"/><circle cx=\"430\" cy=\"115\" r=\"26\" fill=\"#1c1917\"/><path d=\"M420,92L410,52M440,92L450,52\" stroke=\"#57534e\" stroke-width=\"8\" stroke-linecap=\"round\"/><rect x=\"170\" y=\"140\" width=\"14\" height=\"44\" fill=\"#1c1917\"/><rect x=\"210\" y=\"140\" width=\"14\" height=\"44\" fill=\"#1c1917\"/><rect x=\"350\" y=\"140\" width=\"14\" height=\"44\" fill=\"#1c1917\"/><rect x=\"390\" y=\"140\" width=\"14\" height=\"44\" fill=\"#1c1917\"/><rect y=\"184\" width=\"620\" height=\"26\" fill=\"#65a30d\"/><text x=\"430\" y=\"40\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Short, straight, V-shaped horns</text><text x=\"310\" y=\"204\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"#fff\" font-family=\"system-ui,sans-serif\">Found only on Mindoro; about 600 left</text></svg>","c":"A tamaraw, simplified"}]},"cockatoo":{"t":"Some threatened Philippine animals","c":"The Philippine cockatoo, or katala, is a white parrot with a red patch under its tail, found only in the Philippines. Trapping for the pet trade and forest loss reduced it to perhaps a thousand birds, mostly on Palawan, where community wardens, some of them former poachers, now protect nests. It is one of many Philippine species found nowhere else and threatened with extinction. Conservation statuses follow the IUCN Red List and may change.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 232\" width=\"610\" height=\"232\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#a16207\" fill-opacity=\".2\" stroke=\"#a16207\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Philippine eagle</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Critically endangered</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#1c1917\" fill-opacity=\".2\" stroke=\"#1c1917\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Tamaraw</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Critically endangered</text><rect x=\"10\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#94a3b8\" fill-opacity=\".2\" stroke=\"#94a3b8\"/><text x=\"24\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Philippine cockatoo</text><text x=\"24\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Critically endangered</text><rect x=\"310\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#57534e\" fill-opacity=\".2\" stroke=\"#57534e\"/><text x=\"324\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Visayan warty pig</text><text x=\"324\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Critically endangered</text><rect x=\"10\" y=\"158\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"24\" y=\"186\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Philippine tarsier</text><text x=\"24\" y=\"206\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Near threatened</text><rect x=\"310\" y=\"158\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#ca8a04\" fill-opacity=\".2\" stroke=\"#ca8a04\"/><text x=\"324\" y=\"186\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Philippine mouse-deer</text><text x=\"324\" y=\"206\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Endangered</text></svg>","c":"Status of some species found only in the Philippines"}]},"mousedeer":{"t":"The Philippine mouse-deer","c":"The Philippine mouse-deer, or pilandok, lives only on Balabac and a few nearby islands south of Palawan. Despite its name it is neither a mouse nor a true deer but a chevrotain, one of the smallest hoofed mammals in the world, about 40 to 50 centimetres long with legs as thin as pencils. It has no antlers; males have small tusk-like canine teeth instead. In Filipino folklore the pilandok is a clever trickster. It is endangered because of hunting and habitat loss. Simplified.","items":[{"s":"<svg viewBox=\"0 0 420 230\" width=\"420\" height=\"230\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:400px;max-width:100%;height:auto\"><rect width=\"420\" height=\"230\" rx=\"10\" fill=\"#ecfccb\"/><ellipse cx=\"200\" cy=\"130\" rx=\"70\" ry=\"44\" fill=\"#a16207\"/><circle cx=\"276\" cy=\"110\" r=\"26\" fill=\"#a16207\"/><circle cx=\"286\" cy=\"104\" r=\"4\" fill=\"#0f172a\"/><path d=\"M150,166V210\" stroke=\"#a16207\" stroke-width=\"5\"/><path d=\"M180,166V210\" stroke=\"#a16207\" stroke-width=\"5\"/><path d=\"M220,166V210\" stroke=\"#a16207\" stroke-width=\"5\"/><path d=\"M250,166V210\" stroke=\"#a16207\" stroke-width=\"5\"/><path d=\"M292,116l12,4\" stroke=\"#78350f\" stroke-width=\"3\"/><text x=\"210\" y=\"30\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">About 40 cm long: the size of a house cat</text><text x=\"210\" y=\"224\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Legs as thin as a pencil</text></svg>","c":"A mouse-deer, simplified"}]},"cloudrats":{"t":"Cloud rats","c":"Cloud rats are large, furry, mostly tree-dwelling rodents found only in the Philippines, especially in the mountain forests of Luzon. The northern giant cloud rat can weigh over 2 kilograms and measure about 75 centimetres including its long bushy tail. They feed on leaves, shoots and fruit and are active at night. New species of cloud rat are still being discovered by scientists in remote mountains, showing how much remains unknown about Philippine biodiversity. Some species are threatened by forest loss and hunting. Simplified.","items":[{"s":"<svg viewBox=\"0 0 420 230\" width=\"420\" height=\"230\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:400px;max-width:100%;height:auto\"><rect width=\"420\" height=\"230\" rx=\"10\" fill=\"#ecfccb\"/><path d=\"M0,60H420\" stroke=\"#78350f\" stroke-width=\"10\"/><ellipse cx=\"200\" cy=\"120\" rx=\"70\" ry=\"46\" fill=\"#57534e\"/><circle cx=\"270\" cy=\"96\" r=\"26\" fill=\"#57534e\"/><circle cx=\"280\" cy=\"90\" r=\"4\" fill=\"#0f172a\"/><path d=\"M130,120Q60,150 70,200\" fill=\"none\" stroke=\"#57534e\" stroke-width=\"14\" stroke-linecap=\"round\"/><path d=\"M170,84V62\" stroke=\"#57534e\" stroke-width=\"7\"/><path d=\"M230,84V62\" stroke=\"#57534e\" stroke-width=\"7\"/><text x=\"210\" y=\"214\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Bushy-tailed; can weigh over 2 kg</text></svg>","c":"A giant cloud rat on a branch, simplified"}]},"wartypig":{"t":"The Visayan warty pig","c":"The Visayan warty pig is a wild pig found only on a few islands of the western Visayas, mainly Negros and Panay. Males are known for three pairs of fleshy warts on the face and, in the breeding season, a long spiky mane along the back. It is critically endangered, having lost over 95 percent of its former range to deforestation and hunting, and it no longer survives on several islands where it once lived. Breeding programmes in the Philippines and zoos abroad aim to save it. Simplified.","items":[{"s":"<svg viewBox=\"0 0 420 230\" width=\"420\" height=\"230\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:400px;max-width:100%;height:auto\"><rect width=\"420\" height=\"230\" rx=\"10\" fill=\"#ecfccb\"/><ellipse cx=\"200\" cy=\"130\" rx=\"90\" ry=\"48\" fill=\"#57534e\"/><path d=\"M110,120Q80,100 70,130Q80,150 110,140Z\" fill=\"#57534e\"/><circle cx=\"95\" cy=\"118\" r=\"4\" fill=\"#0f172a\"/><path d=\"M150,82l0,-24\" stroke=\"#1c1917\" stroke-width=\"3\"/><path d=\"M156,82l0,-24\" stroke=\"#1c1917\" stroke-width=\"3\"/><path d=\"M162,82l0,-24\" stroke=\"#1c1917\" stroke-width=\"3\"/><path d=\"M168,82l0,-24\" stroke=\"#1c1917\" stroke-width=\"3\"/><path d=\"M174,82l0,-24\" stroke=\"#1c1917\" stroke-width=\"3\"/><path d=\"M180,82l0,-24\" stroke=\"#1c1917\" stroke-width=\"3\"/><path d=\"M186,82l0,-24\" stroke=\"#1c1917\" stroke-width=\"3\"/><path d=\"M192,82l0,-24\" stroke=\"#1c1917\" stroke-width=\"3\"/><path d=\"M198,82l0,-24\" stroke=\"#1c1917\" stroke-width=\"3\"/><path d=\"M204,82l0,-24\" stroke=\"#1c1917\" stroke-width=\"3\"/><path d=\"M210,82l0,-24\" stroke=\"#1c1917\" stroke-width=\"3\"/><path d=\"M216,82l0,-24\" stroke=\"#1c1917\" stroke-width=\"3\"/><path d=\"M222,82l0,-24\" stroke=\"#1c1917\" stroke-width=\"3\"/><path d=\"M228,82l0,-24\" stroke=\"#1c1917\" stroke-width=\"3\"/><rect x=\"140\" y=\"170\" width=\"10\" height=\"36\" fill=\"#57534e\"/><rect x=\"170\" y=\"170\" width=\"10\" height=\"36\" fill=\"#57534e\"/><rect x=\"240\" y=\"170\" width=\"10\" height=\"36\" fill=\"#57534e\"/><rect x=\"270\" y=\"170\" width=\"10\" height=\"36\" fill=\"#57534e\"/><circle cx=\"105\" cy=\"128\" r=\"4\" fill=\"#a8a29e\"/><circle cx=\"118\" cy=\"132\" r=\"4\" fill=\"#a8a29e\"/><text x=\"210\" y=\"30\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Males grow a spiky mane and facial warts</text></svg>","c":"A male Visayan warty pig, simplified"}]},"swiftlets":{"t":"Edible-nest swiftlets","c":"Edible-nest swiftlets are small birds of Southeast Asia that nest high on the walls of dark caves, navigating in darkness by echolocation, using clicking sounds. They build cup-shaped nests almost entirely from strands of their own saliva, which hardens on contact with air. The nests are harvested to make bird’s nest soup, a costly delicacy in Chinese cuisine, at times among the most expensive animal products in the world. Overharvesting has harmed some colonies, so many nests now come from purpose-built swiftlet houses. Simplified.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 210\" width=\"620\" height=\"210\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"210\" rx=\"10\" fill=\"#0b1026\"/><path d=\"M0,0H620V60Q500,40 310,60Q120,80 0,60Z\" fill=\"#57534e\"/><path d=\"M94,62Q120,92 146,62\" fill=\"#fef3c7\" stroke=\"#d6d3d1\"/><path d=\"M184,62Q210,92 236,62\" fill=\"#fef3c7\" stroke=\"#d6d3d1\"/><path d=\"M274,62Q300,92 326,62\" fill=\"#fef3c7\" stroke=\"#d6d3d1\"/><path d=\"M364,62Q390,92 416,62\" fill=\"#fef3c7\" stroke=\"#d6d3d1\"/><path d=\"M454,62Q480,92 506,62\" fill=\"#fef3c7\" stroke=\"#d6d3d1\"/><text x=\"310\" y=\"150\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#e2e8f0\" font-family=\"system-ui,sans-serif\">Nests made almost entirely of the birds’ own hardened saliva</text><text x=\"310\" y=\"172\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"700\" fill=\"#cbd5e1\" font-family=\"system-ui,sans-serif\">Stuck to cave walls; used for bird’s nest soup</text></svg>","c":"Swiftlet nests on a cave ceiling"}]},"seasnakes":{"t":"Sea snakes","c":"Sea snakes are venomous reptiles that live in warm tropical waters of the Indian and Pacific oceans. They evolved from land snakes and have flattened, paddle-shaped tails for swimming. They must surface to breathe air, but some can stay under for over an hour, partly by absorbing oxygen through their skin. Most give birth to live young at sea. Their venom is powerful, but they are generally not aggressive and bites are rare. Sea kraits, banded black and blue, come ashore to rest and lay eggs. Simplified.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 180\" width=\"620\" height=\"180\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"180\" rx=\"10\" fill=\"#bae6fd\"/><path d=\"M30,90Q120,50 210,90T390,90Q470,60 520,90\" fill=\"none\" stroke=\"#1d4ed8\" stroke-width=\"18\" stroke-linecap=\"round\"/><path d=\"M50,82v16\" stroke=\"#facc15\" stroke-width=\"6\"/><path d=\"M98,90.4v16\" stroke=\"#facc15\" stroke-width=\"6\"/><path d=\"M146,91.1v16\" stroke=\"#facc15\" stroke-width=\"6\"/><path d=\"M194,83.4v16\" stroke=\"#facc15\" stroke-width=\"6\"/><path d=\"M242,74.4v16\" stroke=\"#facc15\" stroke-width=\"6\"/><path d=\"M290,72.4v16\" stroke=\"#facc15\" stroke-width=\"6\"/><path d=\"M338,79.2v16\" stroke=\"#facc15\" stroke-width=\"6\"/><path d=\"M386,88.6v16\" stroke=\"#facc15\" stroke-width=\"6\"/><path d=\"M434,91.9v16\" stroke=\"#facc15\" stroke-width=\"6\"/><path d=\"M482,86.1v16\" stroke=\"#facc15\" stroke-width=\"6\"/><path d=\"M520,90L590,60L575,90L590,120Z\" fill=\"#1d4ed8\"/><text x=\"555\" y=\"150\" text-anchor=\"end\" font-size=\"12\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Paddle-shaped tail for swimming</text><text x=\"120\" y=\"30\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Must surface to breathe air</text></svg>","c":"A banded sea snake, simplified"}]},"monitorlizards":{"t":"Some big monitor lizards","c":"Monitor lizards are a group of about 80 species found in Africa, Asia and Australia, including the Komodo dragon, the largest living lizard. They are active hunters with long necks, strong claws and forked tongues that flick out to taste the air, like snakes. Many are good swimmers. The Asian water monitor is common across South and Southeast Asia, including the Philippines, where it is called bayawak, and often lives near people. Lengths are approximate maximums.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 158\" width=\"610\" height=\"158\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#57534e\" fill-opacity=\".2\" stroke=\"#57534e\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Komodo dragon</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Indonesia: up to 3 m</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#4d7c0f\" fill-opacity=\".2\" stroke=\"#4d7c0f\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Asian water monitor</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">South and Southeast Asia: up to 2.5 m</text><rect x=\"10\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#a16207\" fill-opacity=\".2\" stroke=\"#a16207\"/><text x=\"24\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Perentie</text><text x=\"24\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Australia: up to 2.5 m</text><rect x=\"310\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#65a30d\" fill-opacity=\".2\" stroke=\"#65a30d\"/><text x=\"324\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Nile monitor</text><text x=\"324\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Africa: up to 2 m</text></svg>","c":"Four large monitor lizards and where they live"}]},"spice":{"t":"The spice trade through history","c":"For thousands of years, spices such as pepper, cinnamon, cloves and nutmeg were among the world’s most valuable goods, used to flavour and preserve food, in medicine and in religious rituals. Many came from India, Sri Lanka and the Moluccas, the ‘Spice Islands’ of Indonesia. Arab, Indian and Chinese traders carried them across the Indian Ocean and overland. Europe’s desire to reach the sources directly drove the Age of Exploration and the founding of colonial trading empires such as the Dutch and English East India Companies.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 246\" width=\"640\" height=\"246\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"230\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#ea580c\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">3500–2000 BC</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Mesopotamian merchants trade spices</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#ea580c\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1st c. AD</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Roman ships sail to India</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#ea580c\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">800s–1400s</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Arab and Indian traders dominate the Indian Ocean</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#ea580c\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1498</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Vasco da Gama reaches India by sea</text><circle cx=\"140\" cy=\"202\" r=\"8\" fill=\"#ea580c\"/><text x=\"126\" y=\"207\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1600s</text><text x=\"156\" y=\"207\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Dutch and English East India Companies</text></svg>","c":"Milestones of the spice trade"}]},"agri":{"t":"Where farming began","c":"Around 12,000 years ago, people in several parts of the world independently began to farm, growing crops and keeping animals instead of relying only on hunting and gathering. The earliest known farming arose in the Fertile Crescent of the Middle East, and later in China, Mesoamerica, the Andes, New Guinea and parts of Africa, each with its own crops. Farming allowed people to settle in villages, populations to grow and, eventually, cities, writing and states to develop. Dates are approximate.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 232\" width=\"610\" height=\"232\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#a16207\" fill-opacity=\".2\" stroke=\"#a16207\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Fertile Crescent</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Wheat, barley, lentils; sheep, goats</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#dc2626\" fill-opacity=\".2\" stroke=\"#dc2626\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">China</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Rice, millet; pigs</text><rect x=\"10\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"24\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Mesoamerica</text><text x=\"24\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Maize, beans, squash</text><rect x=\"310\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#7c3aed\" fill-opacity=\".2\" stroke=\"#7c3aed\"/><text x=\"324\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Andes</text><text x=\"324\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Potatoes, quinoa; llamas</text><rect x=\"10\" y=\"158\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#0891b2\" fill-opacity=\".2\" stroke=\"#0891b2\"/><text x=\"24\" y=\"186\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">New Guinea</text><text x=\"24\" y=\"206\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Taro, bananas, sugarcane</text><rect x=\"310\" y=\"158\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#f59e0b\" fill-opacity=\".2\" stroke=\"#f59e0b\"/><text x=\"324\" y=\"186\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Africa</text><text x=\"324\" y=\"206\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Sorghum, yams; cattle</text></svg>","c":"Independent centres of early farming and their crops"}]},"fish":{"t":"Farming fish now rivals catching them","c":"For most of history, people ate fish caught from the wild. Since the 1990s the wild catch has levelled off, as many fish stocks are fully exploited or overfished, while aquaculture, the farming of fish, shellfish and seaweed, has grown rapidly and now produces as much as or more than fishing. China is by far the largest producer. Aquaculture eases pressure on wild stocks but can cause pollution and disease if poorly managed. Figures are approximate global totals of aquatic animals, from the UN Food and Agriculture Organization.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 184\" width=\"620\" height=\"184\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><text x=\"160\" y=\"31\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Wild catch, 1990</text><rect x=\"170\" y=\"12\" width=\"274.5\" height=\"28\" rx=\"5\" fill=\"#0891b2\"/><text x=\"452.468085106383\" y=\"31\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">about 86 million tonnes</text><text x=\"160\" y=\"71\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Farmed, 1990</text><rect x=\"170\" y=\"52\" width=\"41.5\" height=\"28\" rx=\"5\" fill=\"#16a34a\"/><text x=\"219.48936170212767\" y=\"71\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">about 13 million</text><text x=\"160\" y=\"111\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Wild catch, 2022</text><rect x=\"170\" y=\"92\" width=\"290.4\" height=\"28\" rx=\"5\" fill=\"#0891b2\"/><text x=\"468.4255319148936\" y=\"111\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">about 91 million</text><text x=\"160\" y=\"151\" text-anchor=\"end\" font-size=\"13\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Farmed, 2022</text><rect x=\"170\" y=\"132\" width=\"300.0\" height=\"28\" rx=\"5\" fill=\"#16a34a\"/><text x=\"478\" y=\"151\" text-anchor=\"start\" font-size=\"12\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">about 94 million</text></svg>","c":"Global fish and seafood production"}]},"potato":{"t":"The potato’s journey","c":"The potato was first domesticated in the Andes of South America, around Lake Titicaca, about 8,000 years ago, where thousands of varieties are still grown. Spanish conquerors brought it to Europe in the late 1500s. It became a staple food, feeding growing populations in Ireland, Germany, Russia and beyond, though Ireland’s heavy reliance on it made the potato blight of 1845–49 a devastating famine. Today it is one of the world’s most important food crops, with China and India the largest producers.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 200\" width=\"620\" height=\"200\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"200\" rx=\"10\" fill=\"#fef3c7\"/><rect x=\"20\" y=\"60\" width=\"170\" height=\"80\" rx=\"10\" fill=\"#c4b5fd\"/><text x=\"105\" y=\"97\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Andes, 8,000 years ago</text><text x=\"105\" y=\"115\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">first domesticated</text><path d=\"M190,100H222\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M230,100l-10,-6v12z\" fill=\"currentColor\"/><rect x=\"230\" y=\"60\" width=\"160\" height=\"80\" rx=\"10\" fill=\"#fde68a\"/><text x=\"310\" y=\"97\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Europe, 1500s</text><text x=\"310\" y=\"115\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">brought by the Spanish</text><path d=\"M390,100H422\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M430,100l-10,-6v12z\" fill=\"currentColor\"/><rect x=\"430\" y=\"60\" width=\"170\" height=\"80\" rx=\"10\" fill=\"#bbf7d0\"/><text x=\"515\" y=\"97\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Worldwide today</text><text x=\"515\" y=\"115\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">a top food crop</text></svg>","c":"From the Andes to the world"}]},"sugar":{"t":"How sugar is made","c":"Most of the world’s sugar comes from sugarcane, a tall tropical grass first domesticated in New Guinea, and sugar beet, grown in cooler climates. The cane is crushed to extract its sweet juice, which is boiled down into syrup until sugar crystals form; the crystals are separated from the leftover molasses and refined into white sugar. Sugar transformed world history: the demand for it drove the Atlantic slave trade and the plantation economies of the Caribbean and Brazil. Health bodies recommend limiting added sugar. Simplified.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 200\" width=\"620\" height=\"200\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"200\" rx=\"10\" fill=\"#f0fdf4\"/><rect x=\"20\" y=\"60\" width=\"140\" height=\"80\" rx=\"10\" fill=\"#bbf7d0\"/><text x=\"90\" y=\"97\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Sugarcane</text><text x=\"90\" y=\"115\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">or sugar beet</text><path d=\"M160,100H182\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M190,100l-10,-6v12z\" fill=\"currentColor\"/><rect x=\"190\" y=\"60\" width=\"120\" height=\"80\" rx=\"10\" fill=\"#e5e7eb\"/><text x=\"250\" y=\"97\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Crushed</text><text x=\"250\" y=\"115\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">juice extracted</text><path d=\"M310,100H332\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M340,100l-10,-6v12z\" fill=\"currentColor\"/><rect x=\"340\" y=\"60\" width=\"120\" height=\"80\" rx=\"10\" fill=\"#fde68a\"/><text x=\"400\" y=\"97\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Boiled</text><text x=\"400\" y=\"115\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">into syrup</text><path d=\"M460,100H482\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M490,100l-10,-6v12z\" fill=\"currentColor\"/><rect x=\"490\" y=\"60\" width=\"110\" height=\"80\" rx=\"10\" fill=\"#f8fafc\"/><text x=\"545\" y=\"97\" text-anchor=\"middle\" font-size=\"13\" font-weight=\"800\" fill=\"#0f172a\" font-family=\"system-ui,sans-serif\">Crystals</text><text x=\"545\" y=\"115\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"600\" fill=\"#1e293b\" font-family=\"system-ui,sans-serif\">refined sugar</text></svg>","c":"From sugarcane to sugar"}]},"maize":{"t":"From wild grass to maize","c":"Maize, or corn, was domesticated about 9,000 years ago in southern Mexico from a wild grass called teosinte, which has only a few small, hard kernels. Over thousands of years farmers selected plants with more and softer kernels, creating the large cobs we know. Maize became the staple of the Maya, Aztecs and many other peoples of the Americas, and after 1492 it spread around the world. Today it is the most produced grain crop on Earth, used for food, animal feed and fuel. Simplified.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 200\" width=\"620\" height=\"200\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"200\" rx=\"10\" fill=\"#fef3c7\"/><path d=\"M60,170V40\" stroke=\"#65a30d\" stroke-width=\"4\"/><path d=\"M60,120q-40,-10 -44,-40M60,110q30,-14 30,-50\" stroke=\"#65a30d\" stroke-width=\"3\" fill=\"none\"/><ellipse cx=\"62\" cy=\"50\" rx=\"5\" ry=\"12\" fill=\"#facc15\"/><text x=\"20\" y=\"190\" text-anchor=\"start\" font-size=\"11\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Teosinte: a few hard kernels</text><path d=\"M380,170V30\" stroke=\"#65a30d\" stroke-width=\"10\"/><ellipse cx=\"420\" cy=\"90\" rx=\"22\" ry=\"60\" fill=\"#facc15\"/><path d=\"M402,44H438\" stroke=\"#ca8a04\"/><path d=\"M402,56H438\" stroke=\"#ca8a04\"/><path d=\"M402,68H438\" stroke=\"#ca8a04\"/><path d=\"M402,80H438\" stroke=\"#ca8a04\"/><path d=\"M402,92H438\" stroke=\"#ca8a04\"/><path d=\"M402,104H438\" stroke=\"#ca8a04\"/><path d=\"M402,116H438\" stroke=\"#ca8a04\"/><path d=\"M402,128H438\" stroke=\"#ca8a04\"/><text x=\"600\" y=\"190\" text-anchor=\"end\" font-size=\"11\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Modern maize: hundreds per cob</text><path d=\"M150,90H312\" stroke=\"currentColor\" stroke-width=\"3\"/><path d=\"M320,90l-10,-6v12z\" fill=\"currentColor\"/></svg>","c":"Teosinte compared with modern maize (simplified)"}]},"beatles":{"t":"The Beatles’ story","c":"The Beatles, formed in Liverpool in 1960, with John Lennon, Paul McCartney, George Harrison and Ringo Starr as the famous line-up, became the best-selling music act of all time. From 1963 their hits and the hysteria of Beatlemania swept Britain and then America, where their 1964 television appearance drew about 73 million viewers. In the studio they pioneered new recording techniques and expanded what pop albums could be. They broke up in 1970, but their songs remain among the most covered ever written.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 246\" width=\"640\" height=\"246\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"230\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1960</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">The Beatles form in Liverpool</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1963</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">‘She Loves You’; Beatlemania begins</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1964</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Appear on The Ed Sullivan Show in the US</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1967</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Sgt. Pepper’s Lonely Hearts Club Band</text><circle cx=\"140\" cy=\"202\" r=\"8\" fill=\"#dc2626\"/><text x=\"126\" y=\"207\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1970</text><text x=\"156\" y=\"207\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">The band breaks up</text></svg>","c":"Milestones of the Beatles"}]},"labor":{"t":"How work has changed","c":"The kind of work most people do has changed dramatically. For most of human history people hunted and gathered; then most became farmers. The Industrial Revolution moved millions into factories, often with long hours and child labour, which led workers to form trade unions and win rights such as the eight-hour day and the weekend. Today, in richer countries, most people work in services such as health, education, retail and offices, while new technologies are again reshaping jobs. Simplified.","items":[{"w":1,"s":"<svg viewBox=\"0 0 600 340\" width=\"600\" height=\"340\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"580\" height=\"56\" rx=\"10\" fill=\"#a16207\" fill-opacity=\".2\" stroke=\"#a16207\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Hunting and gathering</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Most of human history</text><rect x=\"10\" y=\"76\" width=\"580\" height=\"56\" rx=\"10\" fill=\"#65a30d\" fill-opacity=\".2\" stroke=\"#65a30d\"/><text x=\"24\" y=\"104\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Farming</text><text x=\"24\" y=\"124\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">From about 12,000 years ago</text><rect x=\"10\" y=\"142\" width=\"580\" height=\"56\" rx=\"10\" fill=\"#475569\" fill-opacity=\".2\" stroke=\"#475569\"/><text x=\"24\" y=\"170\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Factory work</text><text x=\"24\" y=\"190\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Industrial Revolution, 1700s–</text><rect x=\"10\" y=\"208\" width=\"580\" height=\"56\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"24\" y=\"236\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Services and offices</text><text x=\"24\" y=\"256\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">20th century–</text><rect x=\"10\" y=\"274\" width=\"580\" height=\"56\" rx=\"10\" fill=\"#7c3aed\" fill-opacity=\".2\" stroke=\"#7c3aed\"/><text x=\"24\" y=\"302\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Digital and remote work</text><text x=\"24\" y=\"322\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">21st century</text></svg>","c":"Major eras of work"}]},"michel":{"t":"Michelangelo’s great works","c":"Michelangelo Buonarroti was a sculptor, painter, architect and poet of the Italian Renaissance, considered one of the greatest artists of all time. He carved the Pietà in his early twenties and the 5-metre marble David from a single block that others had rejected. Though he thought of himself mainly as a sculptor, he spent four years painting the ceiling of the Sistine Chapel in the Vatican, covering over 500 square metres with scenes from Genesis, including the Creation of Adam, and later designed the dome of St Peter’s.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 288\" width=\"640\" height=\"288\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"272\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#a16207\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1475</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Born in Caprese, Italy</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#a16207\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1498–99</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Pietà, St Peter’s Basilica</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#a16207\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1501–04</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">David, Florence</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#a16207\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1508–12</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Sistine Chapel ceiling</text><circle cx=\"140\" cy=\"202\" r=\"8\" fill=\"#a16207\"/><text x=\"126\" y=\"207\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1546</text><text x=\"156\" y=\"207\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Chief architect of St Peter’s Basilica</text><circle cx=\"140\" cy=\"244\" r=\"8\" fill=\"#a16207\"/><text x=\"126\" y=\"249\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1564</text><text x=\"156\" y=\"249\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Dies in Rome, aged 88</text></svg>","c":"Milestones in Michelangelo’s life"}]},"stagemagic":{"t":"How misdirection works","c":"Stage magicians create the illusion of the impossible using sleight of hand, hidden devices and psychology. A key technique is misdirection: guiding the audience’s attention to one place, with a gesture, a glance, a joke or a flash of movement, while the secret move happens somewhere else. Research by psychologists shows that people miss surprisingly large things when their attention is elsewhere. Famous magicians include Harry Houdini, the escape artist, and David Copperfield. Magicians traditionally guard their secrets. Simplified.","items":[{"w":1,"s":"<svg viewBox=\"0 0 620 200\" width=\"620\" height=\"200\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect width=\"620\" height=\"200\" rx=\"10\" fill=\"#1c1917\"/><rect x=\"40\" y=\"40\" width=\"200\" height=\"120\" fill=\"#fef3c7\"/><path d=\"M40,160L240,40\" stroke=\"#57534e\" stroke-width=\"2\" stroke-dasharray=\"5 4\"/><text x=\"140\" y=\"190\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"#fde68a\" font-family=\"system-ui,sans-serif\">Magician’s side</text><circle cx=\"430\" cy=\"100\" r=\"50\" fill=\"#7c3aed\"/><text x=\"430\" y=\"190\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"#e2e8f0\" font-family=\"system-ui,sans-serif\">Misdirection: the audience looks here</text><path d=\"M330,100H260\" stroke=\"#facc15\" stroke-width=\"3\"/><text x=\"140\" y=\"28\" text-anchor=\"middle\" font-size=\"12\" font-weight=\"800\" fill=\"#fde68a\" font-family=\"system-ui,sans-serif\">while the secret happens here</text></svg>","c":"Attention drawn away from the secret move"}]},"detective":{"t":"Kinds of mystery stories","c":"Detective fiction began with Edgar Allan Poe’s stories about the investigator Auguste Dupin in the 1840s and was made hugely popular by Arthur Conan Doyle’s Sherlock Holmes. In the ‘golden age’ between the world wars, writers such as Agatha Christie, the best-selling novelist of all time, perfected the puzzle-like whodunit. Later sub-genres include American hardboiled fiction with tough private eyes, cosy mysteries, police procedurals and Scandinavian crime fiction. Readers are invited to solve the mystery alongside the detective.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 158\" width=\"610\" height=\"158\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#7c3aed\" fill-opacity=\".2\" stroke=\"#7c3aed\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Whodunit</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Find the culprit among suspects</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#334155\" fill-opacity=\".2\" stroke=\"#334155\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Hardboiled</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Tough private eyes in gritty cities</text><rect x=\"10\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"24\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Cosy mystery</text><text x=\"24\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Small towns, amateur sleuths</text><rect x=\"310\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"324\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Police procedural</text><text x=\"324\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Realistic police investigation</text></svg>","c":"Four types of mystery fiction"}]},"scifi":{"t":"Common science fiction themes","c":"Science fiction imagines how science and technology might change the world, often to explore human questions. Mary Shelley’s Frankenstein of 1818 is often called the first science fiction novel; Jules Verne and H. G. Wells followed with submarines, time machines and alien invasions. Writers such as Isaac Asimov, who formulated three laws of robotics, Ursula K. Le Guin, Octavia Butler and Liu Cixin have explored robots, space travel, alien contact and future societies. Many real inventions, from submarines to video calls, appeared in science fiction first.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 118\" width=\"610\" height=\"118\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"190\" height=\"44\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Robots and AI</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text><rect x=\"210\" y=\"10\" width=\"190\" height=\"44\" rx=\"10\" fill=\"#7c3aed\" fill-opacity=\".2\" stroke=\"#7c3aed\"/><text x=\"224\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Space travel</text><text x=\"224\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text><rect x=\"410\" y=\"10\" width=\"190\" height=\"44\" rx=\"10\" fill=\"#f59e0b\" fill-opacity=\".2\" stroke=\"#f59e0b\"/><text x=\"424\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Time travel</text><text x=\"424\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text><rect x=\"10\" y=\"64\" width=\"190\" height=\"44\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"24\" y=\"92\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Aliens</text><text x=\"24\" y=\"112\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text><rect x=\"210\" y=\"64\" width=\"190\" height=\"44\" rx=\"10\" fill=\"#dc2626\" fill-opacity=\".2\" stroke=\"#dc2626\"/><text x=\"224\" y=\"92\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Dystopian futures</text><text x=\"224\" y=\"112\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text><rect x=\"410\" y=\"64\" width=\"190\" height=\"44\" rx=\"10\" fill=\"#0891b2\" fill-opacity=\".2\" stroke=\"#0891b2\"/><text x=\"424\" y=\"92\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Cyberpunk</text><text x=\"424\" y=\"112\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\"></text></svg>","c":"Six recurring themes"}]},"circus":{"t":"Acts of the circus","c":"The modern circus began in London in 1768, when Philip Astley, a former cavalryman, performed horse-riding tricks in a ring about 13 metres across, still the standard size today, and soon added acrobats, clowns and jugglers. Travelling circuses spread across Europe and America, famously Barnum & Bailey. Animal acts, once central, have been banned or restricted in many countries over welfare concerns. Contemporary circuses such as Cirque du Soleil focus on acrobatics, music and theatre. Chinese acrobatics has its own ancient tradition.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 158\" width=\"610\" height=\"158\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#dc2626\" fill-opacity=\".2\" stroke=\"#dc2626\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Ringmaster</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Introduces the acts</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#7c3aed\" fill-opacity=\".2\" stroke=\"#7c3aed\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Acrobats and aerialists</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Trapeze and tightrope</text><rect x=\"10\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#f59e0b\" fill-opacity=\".2\" stroke=\"#f59e0b\"/><text x=\"24\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Clowns</text><text x=\"24\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Comedy between acts</text><rect x=\"310\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"324\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Jugglers</text><text x=\"324\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Skill and timing</text></svg>","c":"Classic circus performers"}]},"musicals":{"t":"The parts of a musical","c":"Musical theatre combines songs, spoken dialogue, acting and dance to tell a story. It grew from opera, operetta and vaudeville, and flowered on Broadway in New York and the West End in London in the 20th century, with shows by Rodgers and Hammerstein, Stephen Sondheim and Andrew Lloyd Webber. The Phantom of the Opera ran on Broadway for 35 years, the longest run in its history. Modern hits such as Hamilton mix in hip hop and other styles. Songs often reveal what characters feel when words alone are not enough.","items":[{"w":1,"s":"<svg viewBox=\"0 0 610 158\" width=\"610\" height=\"158\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:600px;max-width:100%;height:auto\"><rect x=\"10\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#2563eb\" fill-opacity=\".2\" stroke=\"#2563eb\"/><text x=\"24\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Overture</text><text x=\"24\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Instrumental opening</text><rect x=\"310\" y=\"10\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#dc2626\" fill-opacity=\".2\" stroke=\"#dc2626\"/><text x=\"324\" y=\"38\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Songs</text><text x=\"324\" y=\"58\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Tell the story and show feelings</text><rect x=\"10\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#16a34a\" fill-opacity=\".2\" stroke=\"#16a34a\"/><text x=\"24\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Dialogue</text><text x=\"24\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Spoken scenes between songs</text><rect x=\"310\" y=\"84\" width=\"290\" height=\"64\" rx=\"10\" fill=\"#7c3aed\" fill-opacity=\".2\" stroke=\"#7c3aed\"/><text x=\"324\" y=\"112\" text-anchor=\"start\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Dance numbers</text><text x=\"324\" y=\"132\" text-anchor=\"start\" font-size=\"12\" font-weight=\"500\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Choreography</text></svg>","c":"Building blocks of a musical"}]},"modernart":{"t":"Movements in modern art","c":"From the late 1800s artists broke away from realistic painting in a rapid series of movements. Impressionists captured light; Fauvists used wild colour; Cubists such as Picasso and Braque showed several viewpoints at once; Dadaists challenged what art could be; Surrealists like Salvador Dalí painted dreams; Abstract Expressionists such as Jackson Pollock dripped and splashed paint; and Pop artists like Andy Warhol drew on advertising and celebrity. Each reacted to what came before and to a changing world. Dates are approximate.","items":[{"w":1,"s":"<svg viewBox=\"0 0 640 372\" width=\"640\" height=\"372\" xmlns=\"http://www.w3.org/2000/svg\" role=\"img\" style=\"width:620px;max-width:100%;height:auto\"><line x1=\"140\" y1=\"20\" x2=\"140\" y2=\"356\" stroke=\"currentColor\" stroke-width=\"2\"/><circle cx=\"140\" cy=\"34\" r=\"8\" fill=\"#7c3aed\"/><text x=\"126\" y=\"39\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1800s</text><text x=\"156\" y=\"39\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Romanticism: emotion and nature</text><circle cx=\"140\" cy=\"76\" r=\"8\" fill=\"#7c3aed\"/><text x=\"126\" y=\"81\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1870s</text><text x=\"156\" y=\"81\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Impressionism: light and colour</text><circle cx=\"140\" cy=\"118\" r=\"8\" fill=\"#7c3aed\"/><text x=\"126\" y=\"123\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1905</text><text x=\"156\" y=\"123\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Fauvism: wild colour</text><circle cx=\"140\" cy=\"160\" r=\"8\" fill=\"#7c3aed\"/><text x=\"126\" y=\"165\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1907</text><text x=\"156\" y=\"165\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Cubism: many viewpoints</text><circle cx=\"140\" cy=\"202\" r=\"8\" fill=\"#7c3aed\"/><text x=\"126\" y=\"207\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1916</text><text x=\"156\" y=\"207\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Dada: anti-art</text><circle cx=\"140\" cy=\"244\" r=\"8\" fill=\"#7c3aed\"/><text x=\"126\" y=\"249\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1924</text><text x=\"156\" y=\"249\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Surrealism: dreams</text><circle cx=\"140\" cy=\"286\" r=\"8\" fill=\"#7c3aed\"/><text x=\"126\" y=\"291\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1940s</text><text x=\"156\" y=\"291\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Abstract Expressionism</text><circle cx=\"140\" cy=\"328\" r=\"8\" fill=\"#7c3aed\"/><text x=\"126\" y=\"333\" text-anchor=\"end\" font-size=\"14\" font-weight=\"800\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">1960s</text><text x=\"156\" y=\"333\" text-anchor=\"start\" font-size=\"13\" font-weight=\"700\" fill=\"currentColor\" font-family=\"system-ui,sans-serif\">Pop Art</text></svg>","c":"Selected movements and roughly when they began"}]}});
